// Кейс: .qa/tests/i18n/I18N-003.md · план: .qa/e2e-app/specs/app.md (1.25)
// RTL по координатам: тексты прижаты вправо на «חשבון», «היסטוריה», «ילדים», «תמיכה». Форма «תמיכה» не заполняется и не отправляется.
// Заголовок «תמיכה» в шапке подэкрана — по центру (так принято 01.11), его не проверяем.
import { by } from '../../lib/appium.mjs';
import { onHome, openTab, assertRightAligned } from '../../lib/banci.mjs';

export const name = 'RTL: тексты прижаты вправо — «חשבון» (заголовок, מנוי, מכשירים, התרעות וצפצוף, תמיכה), «היסטוריה», «ילדים», форма «תמיכה» #50a708 @iphone @app @prod-safe';

const ICON = 90; // справа от подписи строки — иконка (~50 pt от края)

export default async function (app) {
  await onHome(app);

  // 1. «חשבון»: заголовок и подписи строк.
  await openTab(app, 'חשבון');
  await assertRightAligned(app, by.exact('חשבון', 'StaticText'), 'заголовок «חשבון»');
  for (const t of ['מנוי', 'מכשירים', 'התרעות וצפצוף', 'תמיכה']) {
    await app.scrollTo(by.exact(t, 'StaticText'), { what: `строка «${t}» в «חשבון»` });
    await assertRightAligned(app, by.exact(t, 'StaticText'), `подпись строки «${t}»`, { margin: ICON });
  }

  // 2. «חשבון» → «תמיכה»: подписи формы (без ввода и «שליחה»).
  await app.tap(by.exact('תמיכה', 'StaticText'), { what: 'строка «תמיכה»' });
  await app.waitFor(by.contains('נושא הפנייה', 'StaticText'), { what: 'форма «תמיכה» — «נושא הפנייה»' });
  await assertRightAligned(app, by.contains('נושא הפנייה', 'StaticText'), '«נושא הפנייה»');
  await assertRightAligned(app, by.contains('מה תרצו לספר לנו', 'StaticText'), '«מה תרצו לספר לנו?»');
  await assertRightAligned(app, by.contains('אפשר לכתוב עד 2000 תווים', 'StaticText'), '«אפשר לכתוב עד 2000 תווים»');
  await app.restart();
  await onHome(app);

  // 3. «היסטוריה»: заголовок.
  await openTab(app, 'היסטוריה');
  await assertRightAligned(app, by.exact('היסטוריה', 'StaticText'), 'заголовок «היסטוריה»');

  // 4. «ילדים»: заголовок и «הילדים שלנו».
  await openTab(app, 'ילדים');
  await assertRightAligned(app, by.exact('ילדים', 'StaticText'), 'заголовок «ילדים»');
  await app.waitFor(by.begins('הילדים שלנו', 'StaticText'), { what: '«הילדים שלנו» на «ילדים»' });
  await assertRightAligned(app, by.begins('הילדים שלנו', 'StaticText'), '«הילדים שלנו»');
}
